// Processa TODOS os itens (não só o primeiro)
const items = $input.all();
const out = [];

function extrairNumero(data) {
  const key = data?.key || {};
  const candidatos = [
    key.senderPn,
    key.participantPn,
    key.participant,
    data?.sender,
    key.remoteJid,
  ].filter(Boolean);
  for (const cand of candidatos) {
    if (typeof cand !== 'string') continue;
    if (cand.includes('@g.us')) continue;
    if (cand.endsWith('@lid')) continue;
    const n = cand.split('@')[0];
    if (/^\d{8,15}$/.test(n)) return n;
  }
  return null;
}

function isAberto() {
  const now = new Date();
  const utc = now.getTime() + now.getTimezoneOffset() * 60000;
  const sp  = new Date(utc + (-3 * 3600000));
  const day  = sp.getDay();
  const hour = sp.getHours();
  const diasAbertos = [0, 2, 3, 4, 5, 6];
  if (hour >= 19) return diasAbertos.includes(day);
  if (hour < 1)   return diasAbertos.includes(day === 0 ? 6 : day - 1);
  return false;
}

for (const it of items) {
  const body = it.json.body || it.json;
  const data = body.data || {};
  const key  = data.key  || {};
  if (key.fromMe) continue;
  if (key.remoteJid && key.remoteJid.includes('@g.us')) continue;
  const numero = extrairNumero(data);
  if (!numero) { console.log('[bot] sem numero:', JSON.stringify(key)); continue; }
  out.push({ json: { numero, aberto: isAberto(), remoteJid: key.remoteJid } });
}

return out;
